window.DECKS.push({"slug":"hematologi","name":"HOM (Hematologi)","folder":"HEMATOLOGI","questions":[
{"id":"hem-01","p":8,"stem":"Pria 55 tahun mudah lelah sejak 1 bulan, pucat, lemas. TD 90/75, konjungtiva anemis (+), sklera ikterik (–). MCV 64, MCH 22, sel pensil (+). Diagnosis yang tepat adalah…","opts":["Anemia defisiensi B12","Anemia e.c. penyakit kronik","Anemia defisiensi besi","Anemia defisiensi asam folat","Thalasemia"],"ans":2,"why":"Anemia mikrositik hipokromik dengan sel pensil (pencil cell/elliptosit) adalah tanda khas anemia defisiensi besi. Pada pria usia 55 tahun, cari sumber perdarahan saluran cerna. Thalasemia ditandai sel target, sedangkan defisiensi B12/folat menyebabkan anemia makrositik.","ref":[6,7],"tags":["Anemia defisiensi besi","Anemia mikrositik"],"skdi":"4A","src":"slide","cards":[{"q":"Sel khas apusan ADB?","a":"Sel pensil"},{"q":"Sel khas apusan thalasemia?","a":"Sel target"},{"q":"Sel khas apusan anemia megaloblastik?","a":"Hipersegmentasi neutrofil"}]},
{"id":"hem-02","p":8,"stem":"Wanita 26 tahun lemas dan mudah lelah, menstruasi dengan darah banyak setiap kali haid. HR 95. Konjungtiva anemis. Hb 8,7, MCV 72, MCH 20. Diagnosis yang tepat adalah…","opts":["Anemia mikrositik hipokromik e.c. suspek penyakit kronik","Anemia mikrositik hipokromik e.c. suspek defisiensi B12","Anemia makrositik hiperkromik e.c. suspek defisiensi B9","Anemia mikrositik hipokromik e.c. suspek defisiensi besi","Anemia mikrositik hiperkromik e.c. suspek defisiensi B9"],"ans":3,"why":"MCV < 80 dan MCH < 27 berarti anemia mikrositik hipokromik. Pada wanita dengan perdarahan menstruasi berlebihan (kehilangan darah kronik), penyebab tersering adalah defisiensi besi. B12/B9 menyebabkan anemia makrositik.","ref":[6,7],"tags":["Anemia defisiensi besi"],"skdi":"4A","src":"slide","cards":[{"q":"Batas MCV mikrositik?","a":"< 80 fL"},{"q":"Batas MCV makrositik?","a":"> 100 fL"},{"q":"Contoh anemia mikrositik hipokromik?","a":"ADB, thalasemia, ACD, sideroblastik"},{"q":"Contoh anemia normositik?","a":"Hemolitik, aplastik, CKD, perdarahan akut"},{"q":"Penyebab anemia makrositik?","a":"Defisiensi B12/folat"}]},
{"id":"hem-03","p":8,"stem":"Wanita 18 tahun mudah lelah 2 bulan, lemas, mengantuk; tidak suka makan daging. Konjungtiva anemis. Hb 9, MCV 75, MCH 25. Pemeriksaan penunjang yang tepat adalah…","opts":["Schilling test","Coombs test","Elektroforesis Hb","Profil besi","Golongan darah dan rhesus"],"ans":3,"why":"Anemia mikrositik dengan asupan besi heme rendah (tidak makan daging) dicurigai defisiensi besi, dan konfirmasinya dengan profil besi: SI ↓, TIBC ↑, saturasi transferin ↓, feritin ↓. Elektroforesis Hb dipakai bila curiga thalasemia.","ref":[7,10],"tags":["Anemia defisiensi besi"],"skdi":"4A","src":"slide","cards":[{"q":"ADB: feritin?","a":"↓"},{"q":"ADB: TIBC?","a":"↑"},{"q":"Anemia penyakit kronis: feritin?","a":"↑ / normal"},{"q":"Anemia penyakit kronis: TIBC?","a":"↓"}]},
{"id":"hem-04","p":8,"stem":"Anak perempuan 9 tahun sering lemas sejak 1 bulan, kebiasaan suka memakan es batu. Konjungtiva anemis, koilonikia, angular cheilitis. Hb 10 g/dL. Tatalaksana yang tepat adalah…","opts":["Suplementasi besi","Suplementasi asam folat","Suplementasi vitamin B12","Suplementasi vitamin C","Transplantasi sumsum tulang"],"ans":0,"why":"Pica (pagofagia, makan es), koilonikia (kuku sendok), dan cheilitis angularis adalah tanda klinis khas defisiensi besi. Terapinya suplementasi besi oral sampai 2–3 bulan setelah Hb normal.","ref":[7],"tags":["Anemia defisiensi besi"],"skdi":"4A","src":"slide","cards":[{"q":"Tanda klinis khas defisiensi besi?","a":"Koilonikia, cheilitis angularis, atrofi papil lidah, pica (pagofagia), Plummer-Vinson (disfagia)"}]},
{"id":"hem-05","p":11,"stem":"Wanita 65 tahun lemas dan lesu sejak 2 bulan; pasien hemodialisis rutin. Pucat, tanpa splenomegali. Hb 8,3, leukosit 7.000, trombosit 350.000. Tatalaksana yang sesuai adalah…","opts":["Tablet tambah darah","Eritropoetin","Zat besi","Asam folat","Steroid"],"ans":1,"why":"Anemia pada CKD atau hemodialisis terjadi karena ginjal kurang memproduksi eritropoietin. Terapinya eritropoietin (ESA), dengan memastikan cadangan besi cukup lebih dulu.","ref":[9,10],"tags":["Anemia penyakit kronis","CKD"],"skdi":"4A","src":"coretan","cards":[{"q":"Mekanisme & terapi anemia pada CKD?","a":"Defisiensi eritropoietin → normositik normokrom → ESA/eritropoietin (+ penuhi besi)"}]},
{"id":"hem-06","p":11,"stem":"Wanita 52 tahun HT dan DM 5 tahun, tidak rutin kontrol, sangat lemas 1 minggu. Konjungtiva anemis. Hb 7,2, MCV 85, eGFR 25. Kemungkinan hasil serum iron, transferin, saturasi transferin, dan feritin adalah…","opts":["Menurun, menurun, menurun, menurun","Menurun, menurun, normal, normal","Menurun, menurun, menurun, meningkat","Normal, normal, menurun, menurun","Normal, menurun, normal, menurun"],"ans":2,"why":"Anemia penyakit kronis (CKD): hepsidin ↑ menahan besi di makrofag. Hasilnya serum iron ↓, transferin/TIBC ↓, saturasi ↓, dan feritin ↑ (feritin juga reaktan fase akut). Pada ADB feritin ↓ dan TIBC ↑.","ref":[9,10],"tags":["Anemia penyakit kronis"],"skdi":"4A","src":"coretan","cards":[{"q":"ACD: hormon yang meningkat?","a":"Hepsidin"},{"q":"Efek hepsidin ↑?","a":"Besi terperangkap di makrofag"}]},
{"id":"hem-07","p":11,"stem":"Wanita 60 tahun hemodialisis rutin 3×/minggu, gagal ginjal 2 tahun, sangat lemas. Konjungtiva anemis. Hb 7,5, MCV 85, MCH 30, leukosit 6000, trombosit 250.000. Kondisi yang dialami adalah…","opts":["Anemia defisiensi besi","Anemia defisiensi vitamin B12","Anemia on chronic disease","Anemia defisiensi asam folat","Anemia hemolitik"],"ans":2,"why":"Anemia normositik normokromik pada penyakit kronis (gagal ginjal) adalah anemia penyakit kronis (karena defisiensi eritropoietin).","ref":[9],"tags":["Anemia penyakit kronis","CKD"],"skdi":"4A","src":"coretan","cards":[]},
{"id":"hem-08","p":11,"stem":"Perempuan 65 tahun lesu, mudah lelah, napas terengah. Riwayat HT dan CKD tidak rutin kontrol. TD 175/85, konjungtiva anemis, edema anasarka. Hb 7, WBC 4.500, PLT 100.000. Etiologi anemia pada pasien ini adalah…","opts":["Peningkatan ureum dan kreatinin","Defisiensi eritropoietin","Insufisiensi paratiroid","Hipertiroid relatif","Defisiensi vitamin B9"],"ans":1,"why":"Sel interstisial peritubular ginjal menghasilkan eritropoietin. Pada CKD produksinya turun, sehingga terjadi anemia normositik.","ref":[9],"tags":["Anemia penyakit kronis","CKD"],"skdi":"4A","src":"coretan","cards":[]},
{"id":"hem-09","p":14,"stem":"Anak laki-laki 7 tahun tampak pucat dan sering lemas, tanpa riwayat perdarahan atau demam. Paman pasien rutin transfusi darah. Tindakan yang tepat untuk disarankan dokter adalah…","opts":["Tablet tambah darah","Pemeriksaan darah lengkap","Skrining thalasemia","Skrining hemofilia","Pemeriksaan golongan darah"],"ans":2,"why":"Anak pucat dengan riwayat keluarga rutin transfusi mengarah ke thalasemia herediter, sehingga perlu skrining thalasemia (DL + indeks eritrosit, Mentzer, elektroforesis Hb). Jangan langsung memberi besi, karena berisiko iron overload.","ref":[12,13],"tags":["Thalasemia"],"skdi":"2","src":"coretan","cards":[{"q":"Indeks Mentzer: interpretasi?","a":"MCV/RBC < 13 → thalasemia trait; > 13 → defisiensi besi"}]},
{"id":"hem-10","p":14,"stem":"Anak 9 tahun sulit berkonsentrasi di sekolah. Hepar teraba 3 jari BAC. Hb 6, MCV 70, MCH 19. Elektroforesis HbA2 10%, HbF 8%; indeks Mentzer 11. Disarankan transfusi rutin. Komplikasi dan tatalaksananya adalah…","opts":["Iron overload – kortikosteroid","Hemosiderosis – iron chelating agent","Iron overload – IVIg","Hemosiderosis – sulfas ferosus","Anemia – sulfas ferosus"],"ans":1,"why":"Thalasemia β (HbA2 dan HbF ↑) yang ditransfusi rutin akan mengalami penumpukan besi (hemosiderosis) di jantung, hati, dan endokrin. Terapinya kelasi besi (deferoksamin, deferasiroks, deferipron). Pemberian sulfas ferosus justru dikontraindikasikan.","ref":[12,13],"tags":["Thalasemia"],"skdi":"2","src":"coretan","cards":[{"q":"Elektroforesis thalasemia β mayor?","a":"HbA ↓↓, HbA2 ↑, HbF ↑↑"},{"q":"Komplikasi transfusi rutin thalasemia & terapinya?","a":"Hemosiderosis/iron overload → kelasi besi (deferoksamin, deferasiroks, deferipron)"}]},
{"id":"hem-11","p":14,"stem":"Anak laki-laki 7 tahun mudah lelah sejak 1 bulan, pucat; kakaknya pernah mengalami hal sama. Konjungtiva anemis, ikterik, hepatosplenomegali. Apusan darah tepi: anemia mikrositik hipokromik dengan sel target. Diagnosis yang tepat adalah…","opts":["Anemia sideroblastik","Anemia defisiensi folat","Anemia aplastik","Thalasemia","Anemia hemolitik"],"ans":3,"why":"Anemia mikrositik dengan sel target, ikterik, hepatosplenomegali (hemolisis ekstravaskular), dan riwayat keluarga adalah thalasemia.","ref":[12,13],"tags":["Thalasemia"],"skdi":"2","src":"coretan","cards":[]},
{"id":"hem-12","p":14,"stem":"Laki-laki 20 tahun sering lelah dan mengantuk 2 bulan, urin kecoklatan. Membaik setelah transfusi darah. Splenomegali. Hb 7. Pemeriksaan penunjang yang paling tepat adalah…","opts":["Kultur darah","Biopsi sumsum tulang","Apusan darah tepi","Elektroforesis Hb","Uji Schilling"],"ans":3,"why":"Anemia berulang yang membaik dengan transfusi, splenomegali, dan tanda hemolisis (urin cokelat) pada orang muda mengarah ke thalasemia. Pemeriksaan diagnostiknya elektroforesis Hb. Apusan darah tepi hanya skrining. (Catatan dosen: thalasemia, elektroforesis.)","ref":[12,13],"tags":["Thalasemia"],"skdi":"2","src":"coretan","cards":[{"q":"Pemeriksaan diagnostik pasti thalasemia?","a":"Elektroforesis Hb (atau HPLC); analisis DNA untuk mutasi"}]},
{"id":"hem-13","p":17,"stem":"Laki-laki 52 tahun lemas dan pucat. Hb 7, Ht 21%, serum iron meningkat. Apusan: eritrosit dengan Pappenheimer bodies. Aspirasi sumsum tulang: sel berinti dikelilingi cincin besi. Diagnosis yang mungkin adalah…","opts":["Anemia aplastik","Anemia sideroblastik","Anemia megaloblastik","Sferositosis herediter","Anemia defisiensi besi"],"ans":1,"why":"Ring sideroblast (eritroblas dengan cincin besi mitokondria di sumsum tulang), Pappenheimer bodies, dan serum iron ↑ adalah ciri anemia sideroblastik (gangguan sintesis heme).","ref":[15],"tags":["Anemia sideroblastik"],"skdi":"2","src":"coretan","cards":[{"q":"Temuan khas sumsum anemia sideroblastik?","a":"Ring sideroblast (Perls +)"},{"q":"Anemia sideroblastik: SI & feritin?","a":"↑"}]},
{"id":"hem-14","p":17,"stem":"Pria 18 tahun mudah mengantuk sejak 1 bulan, makin berat. Sering nyeri sendi berulang sejak kecil. Kurus, konjungtiva anemis, sklera ikterik, lien Schuffner 3. Hb 8,5, MCV 85, MCH 32, bilirubin indirek ↑. Apusan: sel bulan sabit. Diagnosis yang mungkin adalah…","opts":["Anemia pernisiosa","Sferositosis herediter","AIHA","Sickle cell anemia","Anemia defisiensi G6PD"],"ans":3,"why":"Sel bulan sabit (sickle cell) pada apusan, krisis vaso-oklusif (nyeri sendi/tulang berulang), dan hemolisis (ikterik, bilirubin indirek ↑) adalah sickle cell anemia (HbS, mutasi Glu→Val).","ref":[16],"tags":["Sickle cell"],"skdi":"2","src":"coretan","cards":[{"q":"Sickle cell: mutasi?","a":"Glutamat → valin posisi 6 rantai β (HbS)"},{"q":"Sickle cell: krisis khas?","a":"Krisis vaso-oklusif (nyeri)"},{"q":"Sickle cell: limpa?","a":"Autosplenektomi"}]},
{"id":"hem-15","p":17,"stem":"Pria 21 tahun lemas, letih, lesu 2 minggu, sering mengantuk; keluarga memiliki keluhan sama. Konjungtiva anemis. Hb 10,2, MCV 68, MCH 20, retikulosit 0,3%. Aspirasi sumsum tulang: ring sideroblast (+). Tatalaksana yang tepat adalah…","opts":["Transfusi whole blood","Transfusi packed red cells","Suplementasi piridoksin","Terapi eritropoietin","Suplementasi zat besi"],"ans":2,"why":"Anemia sideroblastik herediter (X-linked, defek ALA sintase yang membutuhkan vitamin B6) diterapi dengan trial piridoksin (B6). Pemberian besi dikontraindikasikan karena besi sudah berlebih. Hb 10 belum perlu transfusi.","ref":[15],"tags":["Anemia sideroblastik"],"skdi":"2","src":"coretan","cards":[{"q":"Terapi anemia sideroblastik herediter?","a":"Piridoksin (vitamin B6), kofaktor ALA sintase; hindari besi"}]},
{"id":"hem-16","p":17,"stem":"Pria 32 tahun lemas 3 minggu; ayahnya memiliki keluhan serupa. Konjungtiva anemis. Hb 9,6, MCV 68, MCH 20, retikulosit 0,3%. Temuan yang SALAH pada diagnosis pasien adalah…","opts":["Basophilic stippling","Ring sideroblast","Perls' stain (–)","Perls' stain (+)","Pappenheimer bodies"],"ans":2,"why":"Pada anemia sideroblastik, pewarnaan Perls (biru Prusia untuk besi) justru POSITIF karena ada ring sideroblast. Jadi 'Perls (–)' adalah temuan yang salah. Basophilic stippling dan Pappenheimer bodies memang dapat ditemukan.","ref":[15],"tags":["Anemia sideroblastik"],"skdi":"2","src":"coretan","cards":[]},
{"id":"hem-17","p":23,"stem":"Laki-laki 30 tahun pusing 2 bulan, lemas, mengantuk. Konjungtiva anemis, sklera ikterik, hepatomegali. MCV 80, MCH 30; anisositosis dan poikilositosis. Diagnosis yang tepat adalah…","opts":["Anemia aplastik","Anemia hemolitik","Anemia penyakit kronis","Anemia megaloblastik","Anemia defisiensi besi"],"ans":1,"why":"Anemia normositik dengan ikterik (bilirubin indirek dari pemecahan eritrosit) dan organomegali menunjukkan anemia hemolitik.","ref":[18,19],"tags":["Anemia hemolitik"],"skdi":"3A","src":"slide","cards":[{"q":"Tanda laboratorium hemolisis?","a":"Bilirubin indirek ↑, LDH ↑, haptoglobin ↓, retikulosit ↑, (urin gelap: hemoglobinuria/urobilinogen)"}]},
{"id":"hem-18","p":23,"stem":"Wanita 23 tahun melahirkan anak pertama normal; bayi tampak kuning dan anemis. Bilirubin total ↑. Bayi golongan A Rh (+), ibu O Rh (+), ayah A Rh (+). Diagnosis yang tepat adalah…","opts":["Inkompatibilitas rhesus","Inkompatibilitas ABO","Sferositosis herediter","Defisiensi G6PD","AIHA"],"ans":1,"why":"Ibu golongan O (memiliki anti-A/anti-B IgG yang dapat melewati plasenta) dengan bayi golongan A atau B adalah inkompatibilitas ABO. Kondisi ini bisa terjadi pada anak PERTAMA. Rhesus ibu dan bayi sama-sama (+), jadi bukan inkompatibilitas Rh.","ref":[21,22],"tags":["Inkompatibilitas ABO","Neonatus"],"skdi":"3A","src":"slide","cards":[{"q":"Inkompatibilitas ABO: golongan darah ibu?","a":"O (bayi A/B)"},{"q":"Inkompatibilitas ABO: bisa pada anak ke-?","a":"Pertama"},{"q":"Inkompatibilitas Rh: terjadi pada anak ke-?","a":"Kedua dst (perlu sensitisasi)"},{"q":"Inkompatibilitas Rh: komplikasi berat?","a":"Hidrops fetalis"}]},
{"id":"hem-19","p":23,"stem":"Bayi usia 1 hari kuning beberapa jam setelah lahir. Bayi menangis kuat, ikterus Kramer 3. Ibu golongan O, bayi golongan B. Pemeriksaan penunjang untuk menegakkan diagnosis adalah…","opts":["Darah rutin","Fungsi hepar","Kadar bilirubin","Coombs test","Apusan darah tepi"],"ans":3,"why":"Ikterus < 24 jam (patologis) dengan ibu O dan bayi B dicurigai penyakit hemolitik karena inkompatibilitas ABO. Bukti antibodi ibu yang melekat pada eritrosit bayi diperoleh dari Coombs test (DAT).","ref":[21,22],"tags":["Inkompatibilitas ABO","Neonatus"],"skdi":"3A","src":"slide","cards":[]},
{"id":"hem-20","p":23,"stem":"Bayi perempuan 5 hari kuning; anak kedua, anak pertama tidak mengalami hal sama. Ikterus Kramer 3, bilirubin total 15, direk 1,2. Ibu golongan A Rh (–), bayi O Rh (+). Kemungkinan penyebab kuning adalah…","opts":["Inkompatibilitas ABO","Inkompatibilitas Rh","Inkompatibilitas ABO dan Rh","Kolestasis neonatal","Hepatitis"],"ans":1,"why":"Ibu Rh (–) dengan bayi Rh (+) pada anak KEDUA (ibu sudah tersensitisasi saat kehamilan pertama) adalah inkompatibilitas Rh. Inkompatibilitas ABO tidak mungkin karena bayi golongan O. Bilirubin direk rendah, jadi bukan kolestasis.","ref":[20,22],"tags":["Inkompatibilitas Rh","Neonatus"],"skdi":"3A","src":"slide","cards":[{"q":"Pencegahan inkompatibilitas Rh?","a":"Anti-D imunoglobulin pada ibu Rh−"},{"q":"Waktu pemberian anti-D?","a":"Minggu ke-28 & ≤ 72 jam pascapersalinan"}]},
{"id":"hem-21","p":26,"stem":"Pria 26 tahun nyeri seluruh perut 3 hari, urin merah kehitaman. Seminggu lalu diare dan diberi kotrimoksazol. Konjungtiva anemis, sklera ikterik, hepatosplenomegali. Hb 7,8, bilirubin unconjugated dan LDH ↑, bite cells pada apusan. Diagnosis yang tepat adalah…","opts":["Anemia defisiensi G6PD","Anemia defisiensi besi","Anemia defisiensi vitamin B9","Anemia defisiensi vitamin B12","Anemia penyakit kronik"],"ans":0,"why":"Hemolisis akut (urin gelap, ikterik, LDH ↑) setelah obat oksidan (kotrimoksazol/sulfa) dengan bite cells (dan Heinz bodies) adalah defisiensi G6PD.","ref":[24],"tags":["G6PD"],"skdi":"2","src":"slide","cards":[{"q":"Temuan apusan & pencetus defisiensi G6PD?","a":"Heinz bodies, bite cells; pencetus oksidan: sulfa/kotrimoksazol, primakuin, dapson, kacang fava, infeksi"}]},
{"id":"hem-22","p":26,"stem":"Anak laki-laki 7 tahun lemas dan mudah lelah 2 hari, makin pucat. Riwayat diare dan mendapat kotrimoksazol dari puskesmas. Hb 8, MCV 85, MCH 30. Apusan: Heinz bodies. Penyebab anemia pada anak ini adalah…","opts":["Defisiensi Fe","Defisiensi G6PD","Defisiensi B12","Defisiensi asam folat","Defisiensi B6"],"ans":1,"why":"Heinz bodies (Hb terdenaturasi akibat stres oksidatif) setelah kotrimoksazol pada anak laki-laki (X-linked) menunjukkan defisiensi G6PD.","ref":[24],"tags":["G6PD"],"skdi":"2","src":"slide","cards":[{"q":"Pola pewarisan defisiensi G6PD?","a":"X-linked resesif (lebih sering laki-laki)"}]},
{"id":"hem-23","p":26,"stem":"Wanita 24 tahun BAK merah kehitaman 2 hari; baru didiagnosis malaria dan sedang minum primakuin. Sklera ikterik, konjungtiva anemis, hepatosplenomegali. Hb 8, bilirubin indirek dan LDH ↑. Apusan: bite cells dan Heinz bodies. Patofisiologi yang mendasari adalah…","opts":["Sekuestrasi parasit ke pembuluh darah","Depresi sel induk progenitor sumsum tulang","Defisiensi substrat pembentuk rantai globin","Maturasi DNA terhambat","Defisiensi enzim eritrosit"],"ans":4,"why":"Defisiensi enzim eritrosit G6PD menyebabkan NADPH ↓ dan glutation tereduksi ↓, sehingga eritrosit tidak tahan stres oksidatif dari primakuin dan terjadi hemolisis. Primakuin wajib didahului skrining G6PD.","ref":[24],"tags":["G6PD","Malaria"],"skdi":"2","src":"slide","cards":[]},
{"id":"hem-24","p":26,"stem":"Bayi laki-laki 4 bulan batuk pilek dan demam ringan, kurang aktif menyusu. Riwayat ikterus dan anemia neonatus. Splenomegali. Hb 7,2, banyak sferosit, defisiensi spektrin α pada analisis protein membran eritrosit. Diagnosis yang tepat adalah…","opts":["Sferositosis herediter","Anemia aplastik","Multiple myeloma","Anemia penyakit kronis","Thalasemia"],"ans":0,"why":"Defek protein membran (spektrin/ankirin) membuat eritrosit berbentuk sferosit yang dihancurkan di limpa. Itu sferositosis herediter: anemia, ikterus, splenomegali. Tes fragilitas osmotik meningkat, dan terapi definitifnya splenektomi.","ref":[25],"tags":["Sferositosis herediter"],"skdi":"2","src":"slide","cards":[{"q":"Sferositosis herediter: defek, tes, terapi?","a":"Defek spektrin/ankirin; fragilitas osmotik ↑, Coombs (−), MCHC ↑; splenektomi"}]},
{"id":"hem-25","p":28,"stem":"Wanita 53 tahun kuning, mudah lelah dan pusing 3 bulan. Konjungtiva anemis, sklera ikterik. Hb 6,9, MCV 90, MCH 30, sferosit (+), Coombs test (+). Tatalaksana yang tepat adalah…","opts":["Suplementasi besi","Kortikosteroid","Antibiotik","Transfusi washed PRC","Transfusi tukar"],"ans":1,"why":"Coombs (+) dengan sferosit adalah AIHA tipe hangat (IgG). Lini pertama kortikosteroid (prednison 1 mg/kgBB). Transfusi hanya bila Hb < 5 atau ada gangguan hemodinamik. (Catatan dosen: warm AIHA, Hb < 5 baru transfusi.)","ref":[27],"tags":["AIHA"],"skdi":"3A","src":"coretan","cards":[{"q":"Terapi lini pertama AIHA hangat?","a":"Prednison 1 mg/kgBB"},{"q":"AIHA refrakter steroid?","a":"Splenektomi / rituximab"}]},
{"id":"hem-26","p":28,"stem":"Pria 27 tahun mudah lelah 1 bulan. Jaundice, sklera ikterik, hepatomegali, splenomegali. Hb 7, bilirubin indirek ↑, uji Coombs direk dan indirek positif. Diagnosis yang tepat adalah…","opts":["Anemia defisiensi besi","Anemia penyakit kronik","Anemia hemolitik autoimun","Thalasemia","Anemia aplastik"],"ans":2,"why":"Hemolisis dengan Coombs test positif (autoantibodi melekat pada eritrosit) adalah anemia hemolitik autoimun.","ref":[27],"tags":["AIHA"],"skdi":"3A","src":"coretan","cards":[{"q":"Coombs direk mendeteksi…?","a":"Antibodi yang melekat di eritrosit"},{"q":"Coombs indirek mendeteksi…?","a":"Antibodi bebas di serum"}]},
{"id":"hem-27","p":28,"stem":"Wanita 54 tahun pusing hilang timbul 2 bulan, mudah lelah, pucat. Tanpa hematemesis atau melena. Konjungtiva anemis, sklera ikterik. Hb 6,5, MCV 93, MCH 34. Pemeriksaan penunjang yang tepat adalah…","opts":["Aspirasi sumsum tulang","Golongan darah dan rhesus","Schilling test","Coombs test","Elektroforesis Hb"],"ans":3,"why":"Anemia normositik dengan ikterik (tanda hemolisis) pada dewasa tanpa perdarahan dicurigai AIHA, sehingga pemeriksaannya Coombs test.","ref":[19,27],"tags":["AIHA"],"skdi":"3A","src":"coretan","cards":[]},
{"id":"hem-28","p":28,"stem":"Wanita 28 tahun mudah lelah 2 bulan, pusing. Konjungtiva anemis, sklera ikterik, splenomegali Schuffner 2. Hb 7, MCV 85, MCH 28. Darah pasien ditetesi reagen dan menggumpal pada suhu > 36°C. Tatalaksana yang paling tepat adalah…","opts":["Transfusi washed PRC","Preparat besi","Transfusi PRC","Transfusi tukar","Kortikosteroid"],"ans":4,"why":"Aglutinasi pada suhu tubuh (> 36°C, IgG) adalah AIHA tipe HANGAT, terapinya kortikosteroid. Tipe dingin (IgM, < 37°C) kurang responsif terhadap steroid; terapinya menghindari dingin atau rituximab. Hb 7 belum indikasi transfusi.","ref":[27],"tags":["AIHA"],"skdi":"3A","src":"coretan","cards":[{"q":"AIHA hangat: antibodi?","a":"IgG"},{"q":"AIHA dingin: antibodi?","a":"IgM"},{"q":"AIHA dingin: infeksi pencetus?","a":"Mycoplasma / EBV"},{"q":"AIHA hangat: penyakit terkait?","a":"SLE, CLL"}]},
{"id":"hem-29","p":31,"stem":"Wanita 27 tahun bercak kemerahan di tubuh 7 hari, mudah lelah, penglihatan kabur, pusing. Tanpa riwayat keluarga. Hb 6,9, leukosit 2.800, trombosit 97.000. Pemeriksaan penunjang yang tepat adalah…","opts":["Aspirasi sumsum tulang","Golongan darah dan rhesus","Schilling test","Coombs test","Elektroforesis Hb"],"ans":0,"why":"Pansitopenia (anemia, leukopenia, trombositopenia) mencurigakan anemia aplastik. Konfirmasinya dengan aspirasi/biopsi sumsum tulang yang menunjukkan gambaran hiposeluler berlemak.","ref":[29,30],"tags":["Anemia aplastik"],"skdi":"2","src":"coretan","cards":[{"q":"Anemia aplastik: definisi & diagnosis?","a":"Pansitopenia + sumsum tulang hiposeluler (diganti lemak), retikulosit ↓"}]},
{"id":"hem-30","p":31,"stem":"Wanita 23 tahun mudah lelah memberat 1 minggu, penglihatan kabur, pusing, mudah memar, gusi berdarah. Hb 7,2, eritrosit 2,9 juta, leukosit 2.000, trombosit 89.000. Histologi sumsum tulang: hiposeluler dengan banyak lemak. Diagnosis yang tepat adalah…","opts":["Limfoma","Leukemia","Anemia aplastik","Sferositosis sekunder","Anemia hemolitik"],"ans":2,"why":"Pansitopenia dengan sumsum tulang hiposeluler berlemak adalah anemia aplastik. Pada leukemia, sumsum tulang justru hiperseluler (penuh blast).","ref":[29,30],"tags":["Anemia aplastik"],"skdi":"2","src":"coretan","cards":[]},
{"id":"hem-31","p":31,"stem":"Perempuan 20 tahun sering mimisan tanpa sebab. Konjungtiva anemis, tanpa ikterik atau organomegali. Hb 8,5, MCV 85, MCHC 35, retikulosit ↓. Aspirasi sumsum tulang: hiposeluler dan berlemak. Terapi definitif yang tepat adalah…","opts":["Infus NaCl 0,9%","Transfusi PRC","Terapi imunosupresif","Transplantasi sumsum tulang","Transfusi trombosit"],"ans":3,"why":"Terapi definitif anemia aplastik pada pasien muda (< 40 tahun) dengan donor HLA-cocok adalah transplantasi sumsum tulang (HSCT). Imunosupresif (ATG + siklosporin) dipakai bila tidak ada donor atau pasien lebih tua. Transfusi hanya suportif.","ref":[29,30],"tags":["Anemia aplastik"],"skdi":"2","src":"coretan","cards":[{"q":"Anemia aplastik usia muda + donor HLA cocok?","a":"Transplantasi sumsum tulang"},{"q":"Anemia aplastik tanpa donor?","a":"ATG + siklosporin"}]},
{"id":"hem-32","p":31,"stem":"Perempuan 23 tahun mudah lelah dan lemas, mudah memar sejak 1 bulan, durasi menstruasi memanjang dari 5 menjadi 10 hari. Konjungtiva anemis, hematom multipel. Hb 6,5, WBC 1500, PLT 150.000. Pemeriksaan penunjang yang tepat adalah…","opts":["Pemeriksaan darah lengkap","Pemeriksaan darah tepi","Uji Schilling","Hb elektroforesis","Biopsi sumsum tulang"],"ans":4,"why":"Bisitopenia dengan tanda perdarahan pada wanita muda dicurigai anemia aplastik (catatan dosen). Diagnosis pastinya dengan biopsi sumsum tulang, yang menilai selularitas lebih baik daripada aspirasi.","ref":[29,30],"tags":["Anemia aplastik"],"skdi":"2","src":"coretan","cards":[]},
{"id":"hem-33","p":33,"stem":"Wanita 37 tahun mudah lemas dan kesemutan kedua tangan sejak operasi lambung 3 bulan lalu. Hb 8,2, MCV 115, MCH 37, MCHC 38. Gambaran sel patognomonis yang ditemukan adalah…","opts":["Sel pensil","Hipersegmentasi neutrofil","Sel target","Pappenheimer bodies","Sel smudge"],"ans":1,"why":"Pascagastrektomi, faktor intrinsik hilang sehingga terjadi defisiensi B12. Akibatnya anemia megaloblastik (MCV > 100) disertai neuropati (kesemutan). Gambaran patognomonisnya hipersegmentasi neutrofil (≥ 6 lobus, atau > 5% dengan 5 lobus).","ref":[32],"tags":["Anemia megaloblastik","B12"],"skdi":"2","src":"slide","cards":[{"q":"Gambaran khas apusan anemia megaloblastik?","a":"Hipersegmentasi neutrofil + makro-ovalosit"}]},
{"id":"hem-34","p":33,"stem":"Laki-laki 45 tahun pusing hilang timbul 1 bulan, mengantuk, tidak bertenaga; vegetarian. Neuropati perifer. Hb 7,3, MCV 102. Schilling test (+). Tatalaksana yang tepat adalah…","opts":["Tiamin","Sianokobalamin","Biotin","Niasin","Asam folat"],"ans":1,"why":"Vegetarian dengan anemia makrositik dan neuropati adalah defisiensi B12 (B12 hanya ada di produk hewani). Terapinya sianokobalamin (B12). Asam folat saja dapat memperbaiki anemia tetapi memperburuk neuropati.","ref":[32],"tags":["Anemia megaloblastik","B12"],"skdi":"2","src":"slide","cards":[{"q":"Pembeda defisiensi B12 vs folat?","a":"B12 ada gejala neurologis"}]},
{"id":"hem-35","p":33,"stem":"Pria 50 tahun lemas sejak 2 minggu, pucat dan mudah lelah; riwayat reseksi usus. Neuropati perifer (+). Hb 8, MCV 103. Kemungkinan etiologi keluhan adalah…","opts":["Defisiensi besi","Defisiensi B9","Defisiensi B12","Perdarahan kronik","Perdarahan akut"],"ans":2,"why":"B12 diserap di ILEUM TERMINAL (kompleks dengan faktor intrinsik). Reseksi usus/ileum menyebabkan defisiensi B12: makrositik + neuropati.","ref":[32],"tags":["Anemia megaloblastik","B12"],"skdi":"2","src":"slide","cards":[{"q":"Lokasi absorpsi B12?","a":"Ileum terminal"},{"q":"B12 butuh apa untuk diabsorpsi?","a":"Faktor intrinsik"},{"q":"Lokasi absorpsi folat?","a":"Jejunum"}]},
{"id":"hem-36","p":33,"stem":"Pria 56 tahun sering mengantuk 3 minggu, pusing dan lemas. Riwayat konsumsi alkohol sejak muda. Kesemutan disangkal. Konjungtiva anemis. Hb 7, MCV 107. Kemungkinan etiologinya adalah…","opts":["Defisiensi besi","Defisiensi B9","Defisiensi B12","Perdarahan kronik","Perdarahan akut"],"ans":1,"why":"Alkoholisme (asupan buruk dan gangguan absorpsi folat) menyebabkan anemia makrositik TANPA gejala neurologis, yaitu defisiensi asam folat (B9).","ref":[32],"tags":["Anemia megaloblastik","Folat"],"skdi":"2","src":"slide","cards":[]},
{"id":"hem-37","p":37,"stem":"Wanita 39 tahun kemerahan pada kulit wajah, mudah lemas, telinga berdenging. Tanpa demam. Splenomegali (+). Hb 22, Hct 66, leukosit 14.000, trombosit 435.000. Diagnosis yang tepat adalah…","opts":["Leukemia","Multiple myeloma","Anemia hemolitik","Polisitemia vera","Polisitemia sekunder"],"ans":3,"why":"Peningkatan ketiga lini (Hb/Hct, leukosit, trombosit), splenomegali, plethora wajah, dan gejala hiperviskositas (tinitus) adalah polisitemia vera (neoplasma mieloproliferatif, JAK2). Polisitemia sekunder hanya meningkatkan eritrosit dan berhubungan dengan hipoksia atau EPO.","ref":[34,35,36],"tags":["Polisitemia vera"],"skdi":"2","src":"slide","cards":[{"q":"Polisitemia vera: EPO?","a":"↓"},{"q":"Polisitemia vera: sel yang naik?","a":"Trilinier (eritrosit, leukosit, trombosit)"},{"q":"Polisitemia sekunder: EPO?","a":"↑"}]},
{"id":"hem-38","p":37,"stem":"Wanita 49 tahun pandangan kabur, telinga berdenging, gatal seluruh badan. Visus 6/30 tidak terkoreksi pinhole, plethora (+), splenomegali (+). Hb 21, Ht 60%, leukosit 13.000, trombosit 465.000. Penyebab kondisi ini adalah…","opts":["Kurangnya produksi eritropoietin","Mutasi BCR-ABL","Kondisi hipoksia kronis","Mutasi JAK2","Defisiensi B12 dan asam folat"],"ans":3,"why":"Polisitemia vera disebabkan mutasi JAK2 V617F (> 95%). BCR-ABL adalah penanda CML. Gatal setelah mandi air hangat (aquagenic pruritus) khas PV.","ref":[35,36],"tags":["Polisitemia vera"],"skdi":"2","src":"slide","cards":[{"q":"Mutasi khas polisitemia vera?","a":"JAK2 V617F"},{"q":"Kromosom Philadelphia = translokasi?","a":"t(9;22)"}]},
{"id":"hem-39","p":37,"stem":"Wanita 39 tahun kemerahan kulit 2 minggu, lemas, telinga berdenging. Makula eritematosa wajah, splenomegali. Hb 25, Hct 66, leukosit 15.000, trombosit 446.000. Tatalaksana yang tepat adalah…","opts":["Flebotomi","Transfusi tukar","Prednison","Hemodialisis","Kemoterapi"],"ans":0,"why":"Terapi utama polisitemia vera adalah flebotomi (target Ht < 45%) ditambah aspirin dosis rendah. Hidroksiurea diberikan bila risiko tinggi.","ref":[36],"tags":["Polisitemia vera"],"skdi":"2","src":"slide","cards":[{"q":"Terapi utama polisitemia vera?","a":"Flebotomi + aspirin dosis rendah"},{"q":"Target Ht flebotomi PV?","a":"< 45%"},{"q":"PV risiko tinggi: sitoreduksi?","a":"Hidroksiurea"}]},
{"id":"hem-40","p":37,"stem":"Pria 44 tahun sakit kepala 3 minggu, gatal seluruh tubuh, telinga berdenging, penglihatan buram. TD 170/90, lien Schuffner II. Hb 19,8, Ht 57%, eritrosit 8,5 juta, leukosit 12.500, trombosit 550.000. Temuan penunjang yang mungkin adalah…","opts":["Biopsi sumsum tulang hiposeluler","Biopsi sumsum tulang hiperselularitas trilinier","Biopsi sumsum tulang fried-egg appearance","Darah tepi hipersegmentasi neutrofil","Darah tepi Pappenheimer bodies"],"ans":1,"why":"Polisitemia vera: sumsum tulang hiperseluler pada ketiga lini (panmielosis). Gambaran hiposeluler terdapat pada anemia aplastik, dan fried-egg pada sel plasma/oligodendroglioma.","ref":[35,36],"tags":["Polisitemia vera"],"skdi":"2","src":"slide","cards":[]},
{"id":"hem-41","p":42,"stem":"Anak perempuan ruam kemerahan di tubuh sejak 5 hari; baru pulang rawat inap 1 minggu lalu karena ISPA. Mudah lelah. Ruam merah keunguan yang dapat dipalpasi. Hasil darah rutin yang paling mungkin adalah…","opts":["Leukositosis","Trombositopenia","Peningkatan BT dan CT","Megatrombosit","Dalam batas normal"],"ans":4,"why":"Palpable purpura setelah ISPA pada anak adalah Henoch-Schönlein purpura (vaskulitis IgA). Trombosit dan faal koagulasi NORMAL, karena purpura timbul dari kerusakan pembuluh darah, bukan gangguan trombosit.","ref":[40,41],"tags":["HSP","Hemostasis"],"skdi":"3A","src":"slide","cards":[{"q":"HSP: tetrad klinis?","a":"Purpura palpable, artralgia, nyeri perut, nefritis"},{"q":"HSP: trombosit & koagulasi?","a":"Normal"},{"q":"HSP: jenis vaskulitis?","a":"Vaskulitis IgA"}]},
{"id":"hem-42","p":42,"stem":"Anak perempuan 15 tahun ruam di kaki dan tangan 1 minggu, merah kebiruan seperti memar. Riwayat ISPA. Trombosit 32.000. Diagnosis yang paling mungkin adalah…","opts":["vWD","ITP","DIC","HSP","SLE"],"ans":1,"why":"Trombositopenia terisolasi dengan purpura atau memar setelah infeksi virus adalah ITP (autoantibodi terhadap trombosit). Pada HSP trombosit normal, sedangkan pada DIC PT/aPTT memanjang dan D-dimer ↑.","ref":[41],"tags":["ITP","Hemostasis"],"skdi":"3A","src":"slide","cards":[{"q":"ITP: patogenesis & terapi?","a":"Autoantibodi IgG anti-trombosit → trombositopenia terisolasi; kortikosteroid (± IVIG); anak sering self-limited"}]},
{"id":"hem-43","p":42,"stem":"Anak perempuan 9 tahun bercak kemerahan di kedua kaki, tidak gatal atau nyeri, disertai nyeri sendi. Palpable purpura (+). Diagnosis yang tepat adalah…","opts":["DIC","HSP","ITP","vWD","Dermatitis"],"ans":1,"why":"Palpable purpura di tungkai bawah disertai artralgia pada anak adalah Henoch-Schönlein purpura (IgA vasculitis).","ref":[41],"tags":["HSP"],"skdi":"3A","src":"slide","cards":[]},
{"id":"hem-44","p":42,"stem":"Anak 13 tahun sering mimisan dan gusi berdarah 1 bulan, bercak merah di beberapa bagian tubuh; mimisan berulang sejak kecil. Hb 11,5, leukosit 8500, trombosit 250.000, BT memanjang, PT normal, aPTT memanjang. Pemeriksaan spesifik yang mendukung diagnosis adalah…","opts":["D-dimer","INR","Tes ristocetin","Faktor VIII","Fibrin degradation product"],"ans":2,"why":"Perdarahan mukokutan (mimisan, gusi) dengan BT memanjang (gangguan fungsi trombosit) DAN aPTT memanjang (faktor VIII ↓ sekunder) pada trombosit normal mengarah ke von Willebrand disease. Uji spesifiknya ristocetin cofactor activity (agregasi trombosit dengan ristocetin) atau antigen vWF.","ref":[40,41,45],"tags":["vWD","Hemostasis"],"skdi":"3A","src":"slide","cards":[{"q":"vWD: BT?","a":"Memanjang"},{"q":"vWD: aPTT?","a":"Memanjang (± F VIII ↓)"},{"q":"Tes spesifik vWD?","a":"Ristocetin / vWF:Ag"}]},
{"id":"hem-45","p":44,"stem":"Pria 25 tahun sering memar pada persendian sejak kecil; riwayat perdarahan lama saat khitan. Hemartrosis (+). Hb 13, trombosit 260.000, CT memanjang, aPTT memanjang, aktivitas faktor IX rendah. Diagnosis yang tepat adalah…","opts":["ITP","DIC","Hemofilia A","Hemofilia B","Von Willebrand disease"],"ans":3,"why":"Laki-laki dengan hemartrosis dan aPTT memanjang adalah hemofilia. Hemofilia B (Christmas disease) bila faktor IX rendah; hemofilia A bila faktor VIII rendah.","ref":[43],"tags":["Hemofilia","Hemostasis"],"skdi":"2","src":"coretan","cards":[{"q":"Hemofilia A: defisiensi faktor?","a":"VIII"},{"q":"Hemofilia B: defisiensi faktor?","a":"IX"},{"q":"Hemofilia: pola pewarisan?","a":"X-linked resesif"},{"q":"Hemofilia: hasil lab?","a":"aPTT memanjang, PT & BT normal"}]},
{"id":"hem-46","p":44,"stem":"Anak laki-laki 4 tahun bercak kemerahan di sendi dan lutut sejak kecil. Hemartrosis (+). Clotting time memanjang, aPTT memanjang, penurunan faktor VIII. Diagnosis dan tatalaksana yang tepat adalah…","opts":["Hemolisis of the newborn; PRC","Hemofilia A; kriopresipitat","Hemofilia B; FFP","Thalasemia; PRC","ITP; steroid"],"ans":1,"why":"Faktor VIII ↓ berarti hemofilia A. Terapinya konsentrat faktor VIII. Bila tidak tersedia, kriopresipitat (kaya FVIII, fibrinogen, vWF). Hemofilia B diterapi dengan FIX atau FFP.","ref":[43],"tags":["Hemofilia","Hemostasis"],"skdi":"2","src":"coretan","cards":[{"q":"Terapi hemofilia A bila konsentrat FVIII tidak ada?","a":"Kriopresipitat (FVIII, fibrinogen, vWF, FXIII); hemofilia B → FFP / konsentrat FIX"}]},
{"id":"hem-47","p":44,"stem":"Bayi perempuan 3 hari perdarahan hidung sulit berhenti; persalinan oleh dukun beranak usia 38 minggu. Keadaan umum baik, fontanel cembung (+). Hb 13,2, leukosit 11.000, trombosit 170.000, PT memanjang. Diagnosis yang mungkin adalah…","opts":["Vitamin K deficiency bleeding","Hemofilia","Von Willebrand disease","Pseudohemofilia","ITP"],"ans":0,"why":"Bayi yang lahir dengan dukun tidak mendapat injeksi vitamin K1 profilaksis. Faktor II, VII, IX, dan X turun, sehingga PT memanjang (faktor VII paling sensitif). Itu vitamin K deficiency bleeding. Fontanel cembung mengarah ke perdarahan intrakranial.","ref":[43],"tags":["VKDB","Neonatus"],"skdi":"3A","src":"coretan","cards":[{"q":"Faktor pembekuan tergantung vitamin K?","a":"II, VII, IX, X"},{"q":"Profilaksis VKDB pada bayi baru lahir?","a":"Vitamin K1 1 mg IM dosis tunggal setelah lahir"},{"q":"Defisiensi vitamin K: tes yang memanjang dulu?","a":"PT"}]},
{"id":"hem-48","p":44,"stem":"Bayi perempuan 3 hari perdarahan hidung sulit berhenti, persalinan oleh dukun. Fontanel cembung (+), trombosit 170.000, PT memanjang. Tatalaksana yang sesuai adalah…","opts":["Vitamin K1 2 mg PO","Vitamin K1 2 mg IV","Vitamin K3 2 mg IM","Vitamin K2 2 mg PO","Vitamin K2 2 mg IV"],"ans":1,"why":"VKDB dengan perdarahan aktif diterapi vitamin K1 (fitomenadion) 1–2 mg IV/SC, ditambah FFP bila perdarahan berat. Vitamin K3 (menadion) berisiko hemolisis dan kernikterus pada neonatus. (Catatan dosen: vit K1 1–2 mg IV/SC.)","ref":[43],"tags":["VKDB","Neonatus"],"skdi":"3A","src":"coretan","cards":[{"q":"Terapi VKDB (perdarahan aktif)?","a":"Vitamin K1 (fitomenadion) 1–2 mg IV/SC ± FFP; hindari K3 (hemolisis)"}]},
{"id":"hem-49","p":46,"stem":"Perempuan 20 tahun bengkak kemerahan di leher belakang setelah digigit tomcat beberapa jam lalu; hiperemis, edema, nyeri tekan. Hb 11, leukosit 8.000, trombosit 110.000, BT dan CT meningkat, D-dimer meningkat. Diagnosis yang tepat adalah…","opts":["Reaksi anafilaktik","Deep vein thrombosis","Disseminated intravascular coagulation","ITP","Von Willebrand disease"],"ans":2,"why":"Trombositopenia, BT dan CT memanjang (konsumsi trombosit dan faktor), serta D-dimer ↑ (fibrinolisis) adalah DIC (gangguan hemostasis campuran). Pencetusnya toksin, sepsis, trauma, atau obstetri.","ref":[45],"tags":["DIC","Hemostasis"],"skdi":"3A","src":"slide","cards":[{"q":"Profil lab DIC?","a":"Trombosit ↓, PT & aPTT memanjang, fibrinogen ↓, D-dimer/FDP ↑, schistosit"}]},
{"id":"hem-50","p":46,"stem":"Perempuan P2A0 29 tahun penurunan kesadaran; melahirkan dengan dukun 4 hari lalu. Sebelumnya mimisan dan bintik merah di badan. Purpura abdomen dan ekstremitas. Hb 8, leukosit 5.000, trombosit 88.000, PT dan aPTT memanjang. Pemeriksaan tambahan yang diperlukan adalah…","opts":["Apus darah tepi","Faktor koagulasi","Sumsum tulang","D-dimer","Profil besi"],"ans":3,"why":"Komplikasi obstetri dengan perdarahan, trombositopenia, dan PT/aPTT memanjang mengarah ke DIC. Bukti aktivasi fibrinolisis diperoleh dengan D-dimer (bagian dari skor ISTH DIC).","ref":[45],"tags":["DIC","Hemostasis"],"skdi":"3A","src":"slide","cards":[]},
{"id":"hem-51","p":46,"stem":"Perempuan 31 tahun hamil 8 bulan, nyeri dan kemerahan betis kanan sejak 1 bulan, tungkai hangat, nyeri saat dorsofleksi pasif (Homan +). Pemeriksaan gold standard untuk kasus ini adalah…","opts":["USG vena","Arteriografi","Ankle brachial index","MRI","Contrast venography"],"ans":4,"why":"Curiga DVT (kehamilan, Homan sign). Gold standard diagnosisnya venografi kontras. Dalam praktik, pemeriksaan awal yang dipakai adalah USG Doppler kompresi (non-invasif).","ref":[45],"tags":["DVT","Hemostasis"],"skdi":"3A","src":"slide","cards":[{"q":"Gold standard DVT?","a":"Venografi kontras"},{"q":"Pemeriksaan awal/praktis DVT?","a":"USG Doppler kompresi"}]},
{"id":"hem-52","p":46,"stem":"Wanita 40 tahun nyeri tungkai sejak 1 hari setelah penerbangan 20 jam dari Amerika, bengkak dan kemerahan di tungkai, tanpa vena berkelok. Komplikasi yang berbahaya pada kasus ini adalah…","opts":["Emboli paru","Ulkus vena","Selulitis","Varises","Limb ischemia"],"ans":0,"why":"Imobilisasi lama (penerbangan jauh, sesuai trias Virchow) menyebabkan DVT. Komplikasi paling berbahaya adalah trombus yang lepas menjadi emboli paru.","ref":[45],"tags":["DVT"],"skdi":"3A","src":"slide","cards":[{"q":"Trias Virchow?","a":"Stasis aliran darah, kerusakan endotel, hiperkoagulabilitas"}]},
{"id":"hem-53","p":52,"stem":"Wanita 60 tahun benjolan di leher 3 bulan, makin membesar, mudah lelah, keringat malam, BB turun. Massa soliter regio colli, kenyal, mobile, tidak nyeri. Gambaran Reed-Sternberg cell. Diagnosis yang tepat adalah…","opts":["Limfadenitis","Limfoma Burkitt","Limfoma non-Hodgkin","Limfoma Hodgkin","Limfadenopati"],"ans":3,"why":"Limfadenopati tidak nyeri dengan gejala B (demam, keringat malam, BB turun) dan sel Reed-Sternberg adalah limfoma Hodgkin.","ref":[50,51],"tags":["Limfoma Hodgkin"],"skdi":"2","src":"coretan","cards":[{"q":"Sel khas limfoma Hodgkin?","a":"Reed-Sternberg (owl eye, CD15+ CD30+)"},{"q":"Gejala B limfoma?","a":"Demam > 38°C, keringat malam, BB turun > 10% dalam 6 bulan"}]},
{"id":"hem-54","p":52,"stem":"Wanita 48 tahun benjolan di leher 4 minggu, demam, keringat malam, lemas, BB turun drastis 1 bulan. Gambaran 'owl eye'. Patofisiologi yang paling tepat adalah…","opts":["Aktivasi protoonkogen akibat translokasi kromosom","Transformasi maligna sel induk hematopoietik pluripoten","Aktivasi gen supresor tumor akibat delesi kromosom","Hilangnya fenotipe sel B akibat mutasi sel B germinal","Proliferasi seluler folikel limfoid"],"ans":3,"why":"Sel Reed-Sternberg (owl eye) pada limfoma Hodgkin berasal dari sel B germinal center yang mengalami mutasi dan kehilangan fenotipe sel B (tidak mengekspresikan CD20 atau Ig). Translokasi protoonkogen adalah mekanisme limfoma non-Hodgkin, misalnya Burkitt t(8;14).","ref":[51],"tags":["Limfoma Hodgkin"],"skdi":"2","src":"coretan","cards":[]},
{"id":"hem-55","p":52,"stem":"Pria 55 tahun nyeri ketiak 3 hari; riwayat luka di lengan atas. Benjolan ketiak nyeri dan panas. Kemerahan membentuk alur. Kemungkinan diagnosis adalah…","opts":["Limfangitis","Limfadenitis B","Limfoma Hodgkin","Limfadenitis TB","Limfedema"],"ans":0,"why":"Garis kemerahan (red streak) yang menjalar dari luka ke arah KGB regional adalah limfangitis (infeksi saluran limfe, biasanya Streptococcus).","ref":[48,49],"tags":["Limfangitis"],"skdi":"4A","src":"coretan","cards":[{"q":"Limfangitis: tanda khas?","a":"Garis merah (red streak)"},{"q":"Limfadenitis: tanda khas?","a":"Benjolan KGB nyeri"}]},
{"id":"hem-56","p":52,"stem":"Laki-laki 32 tahun benjolan di leher 3 minggu, demam tidak tinggi, BB turun, lemas. Suhu 37,4°C. Nodul multipel servikal ukuran terbesar 1,8 cm, lunak, tidak nyeri. Rontgen toraks: infiltrat apeks paru kiri. Diagnosis yang paling tepat adalah…","opts":["Limfadenitis tuberkulosa","Limfadenitis viral","Leukemia akut","Leukemia kronik","Limfoma"],"ans":0,"why":"Limfadenopati servikal multipel yang tidak nyeri (scrofula), gejala konstitusional, dan infiltrat di apeks paru mengarah ke limfadenitis TB.","ref":[48,49],"tags":["Limfadenitis TB"],"skdi":"4A","src":"coretan","cards":[]},
{"id":"hem-57","p":57,"stem":"Wanita 40 tahun demam ringan 7 hari, BB turun 12 kg dalam 1 bulan, mudah lelah. Konjungtiva anemis. Hb 7, Hct 30%, leukosit 87.000, trombosit 400.000. Apusan: smudge cell. Diagnosis kasus ini adalah…","opts":["AML","CML","ALL","CLL","Limfoma Hodgkin"],"ans":3,"why":"Smudge cell (limfosit rapuh yang pecah saat apusan) dengan leukositosis limfositik adalah CLL.","ref":[53,54,55],"tags":["Leukemia","CLL"],"skdi":"2","src":"slide","cards":[{"q":"Temuan khas AML?","a":"Auer rod"},{"q":"Temuan khas CML?","a":"Kromosom Philadelphia (BCR-ABL)"},{"q":"Temuan khas ALL?","a":"Limfoblas, usia anak"},{"q":"Temuan khas CLL?","a":"Smudge cell, usia lansia"}]},
{"id":"hem-58","p":57,"stem":"Wanita 25 tahun lemas 3 bulan, pusing dan mudah mengantuk. Hb 8, leukosit 150.000, blast 80%, Auer rod (+). Diagnosis yang tepat adalah…","opts":["AML","CML","ALL","CLL","Limfoma Hodgkin"],"ans":0,"why":"Blast ≥ 20% berarti leukemia akut. Auer rod (kristal granula azurofilik) patognomonis untuk mieloblas, sehingga diagnosisnya AML. AML M3 (APL) disertai DIC dan diterapi ATRA.","ref":[53,54,55],"tags":["Leukemia","AML"],"skdi":"2","src":"slide","cards":[]},
{"id":"hem-59","p":57,"stem":"Pria 67 tahun nyeri badan, lemas, mudah lelah, jarang BAK. HR 108. Konjungtiva anemis. Hb 8, WBC 6500, PLT 145.000; kalsium, asam urat, kreatinin ↑. Urinalisis: protein Bence-Jones (+). Diagnosis yang tepat adalah…","opts":["Limfoma Hodgkin","Leukemia akut","Leukemia kronis","Multiple myeloma","Hemofilia"],"ans":3,"why":"Kriteria CRAB (hiperkalsemia, gangguan ginjal, anemia, lesi tulang/nyeri tulang) dengan protein Bence-Jones (rantai ringan) di urin pada lansia adalah multiple myeloma.","ref":[56],"tags":["Multiple myeloma"],"skdi":"1","src":"slide","cards":[{"q":"Kriteria CRAB multiple myeloma?","a":"HyperCalcemia, Renal insufficiency, Anemia, Bone lesions (litik/punched-out)"},{"q":"Multiple myeloma: temuan urin?","a":"Protein Bence-Jones"},{"q":"Multiple myeloma: elektroforesis protein?","a":"M-spike"},{"q":"Multiple myeloma: apusan darah?","a":"Rouleaux"},{"q":"Multiple myeloma: sel plasma sumsum?","a":"> 10%"}]},
{"id":"hem-60","p":57,"stem":"Wanita 75 tahun nyeri punggung memberat 4 bulan. Nyeri tekan vertebra torakal 4–6. Rontgen: gambaran litik. Dokter menyarankan biopsi sumsum tulang. Sel patognomonis yang dapat ditemukan adalah…","opts":["Mieloblas","Sel myeloma","Sel Reed-Sternberg","Eritrosit membesar","Sickle cell"],"ans":1,"why":"Lesi litik tulang pada lansia mengarah ke multiple myeloma. Biopsi sumsum tulang menunjukkan sel plasma ganas (sel myeloma) > 10%.","ref":[56],"tags":["Multiple myeloma"],"skdi":"1","src":"slide","cards":[]},
{"id":"hem-61","p":61,"stem":"Perempuan sesak napas 30 menit setelah makan kepiting (pertama kali). TD 80/63, N 125, RR 30, palpebra edema, kemerahan seluruh tubuh. Tatalaksana awal yang tepat adalah…","opts":["Inj. metilprednisolon","Rehidrasi dengan koloid","Inj. epinefrin","Inj. hidrokortison","Inj. difenhidramin"],"ans":2,"why":"Syok anafilaktik (hipotensi + gejala kulit/napas setelah alergen) diterapi pertama dengan epinefrin IM. Kortikosteroid dan antihistamin hanya terapi tambahan.","ref":[59,60],"tags":["Anafilaksis"],"skdi":"4A","src":"slide","cards":[{"q":"Dosis epinefrin anafilaksis dewasa?","a":"0,3–0,5 mg (1:1000) IM"},{"q":"Lokasi injeksi epinefrin anafilaksis?","a":"Anterolateral paha"},{"q":"Epinefrin anafilaksis: diulang tiap…?","a":"5–15 menit"}]},
{"id":"hem-62","p":61,"stem":"Perempuan 22 tahun penurunan kesadaran setelah suntikan obat pemutih di salon. Somnolen, TD 80/50, HR 130, RR 32, edema periorbital (+), akral dingin. Diagnosis yang paling tepat adalah…","opts":["Hipoglikemia","Syok hipovolemik","Refleks vagal","Syok kardiogenik","Reaksi anafilaktik"],"ans":4,"why":"Syok mendadak (hipotensi, takikardia) dengan angioedema (edema periorbital) segera setelah paparan obat suntik adalah reaksi anafilaktik. Refleks vagal menyebabkan BRADIKARDIA.","ref":[59,60],"tags":["Anafilaksis"],"skdi":"4A","src":"slide","cards":[{"q":"Anafilaksis: nadi?","a":"Takikardia"},{"q":"Sinkop vasovagal: nadi?","a":"Bradikardia"}]},
{"id":"hem-63","p":61,"stem":"Pria 38 tahun sesak napas 1 jam setelah injeksi kontras untuk CT scan kepala. TD 80/60, HR 120, RR 26. Tatalaksana farmakologi utama yang paling tepat adalah…","opts":["Oksigen 15 lpm","Hidrokortison IM 200 mg","Klorfeniramin IM 10 mg","Adrenalin 1:1000 IM 0,5 mL","Adrenalin 1:1000 IV 0,5 mL"],"ans":3,"why":"Anafilaksis diterapi adrenalin 1:1000 sebanyak 0,5 mL (0,5 mg) secara IM. Adrenalin 1:1000 tidak boleh diberikan IV bolus (risiko aritmia/infark); bila IV harus diencerkan dan dititrasi oleh ahli. Oksigen bukan terapi farmakologi utama.","ref":[60],"tags":["Anafilaksis"],"skdi":"4A","src":"slide","cards":[]},
{"id":"hem-64","p":61,"stem":"Wanita 20 tahun mata kanan merah 7 hari, gatal, cairan bening. Riwayat sering bersin pagi hari dan alergi udang; keluhan berulang. Tanpa penurunan penglihatan. Gambaran cobblestone (+). Etiologi yang tepat adalah…","opts":["Reaksi inflamasi akibat infeksi bakteri","Reaksi inflamasi non-infeksi","Reaksi hipersensitivitas tipe I","Reaksi hipersensitivitas tipe IV","Proses degeneratif"],"ans":2,"why":"Konjungtivitis vernal/alergi (gatal, berulang, atopi, papil cobblestone di konjungtiva tarsal) adalah hipersensitivitas tipe I yang diperantarai IgE dan sel mast.","ref":[58],"tags":["Hipersensitivitas"],"skdi":"4A","src":"slide","cards":[{"q":"Hipersensitivitas tipe I: mediator?","a":"IgE (anafilaksis, alergi)"},{"q":"Hipersensitivitas tipe II: mekanisme?","a":"Antibodi sitotoksik (AIHA, reaksi transfusi)"},{"q":"Hipersensitivitas tipe III: mekanisme?","a":"Kompleks imun (SLE, PSGN)"},{"q":"Hipersensitivitas tipe IV: mekanisme?","a":"Sel T (dermatitis kontak, tuberkulin)"}]},
{"id":"hem-x01","lat":"pj-int2","ln":14,"lp":5,"stem":"Seorang perempuan usia 45 tahun datang ke poli penyakit dalam dengan keluhan emas dan mudah lelah 1 2 bulan ini. Keluhan disertai dengan rasa nyeri di perut. Dari hasil pemeriksaan fisik didapatkan TTV dalam batas normal, CA (+/+), SI (+/+), splenomegaly. Dari hasil pemeriksaan laboratorium didapatkan Hb 8.0, trombosit 250.000, leukosit 8.000, retikulosit 4.2%, direct antiglobulin test (+). Produk darah apa yang dapat diberikan untuk pasien?","opts":["Packed Red Cells","Whole Blood","Thrombocyte Concetrate","Washed Red Cells","Albumin"],"ans":3,"why":"Anemia, ikterik, splenomegali, retikulosit ↑, DAT/Coombs (+) → AIHA. Bila perlu transfusi, beri WASHED red cells (sel darah merah dicuci; mengurangi plasma/antibodi dan reaksi transfusi).","ref":[27],"tags":["AIHA","Transfusi"],"skdi":"3A","src":"kunci","cards":[{"q":"Komponen darah pada AIHA bila perlu transfusi?","a":"Washed red cells"},{"q":"AIHA: tes kunci?","a":"Direct antiglobulin test (Coombs) +"}]},
{"id":"hem-x02","lat":"pj-int2","ln":15,"lp":5,"stem":"Seorang perempuan usia 45 tahun datang ke poli penyakit dalam dengan dengan keluhan benjolan di leher sebelah kanan di daerah supraklavikula dan ketiak kanan sebesar telur puyuh sejak 3 bulan. Pasien juga mengeluh sering demam, keluar keringat pada malam hari dan berat badan turun drastis 8 kg dalam 2 bulan terakhir. Apakah pemeriksaan baku emas untuk menentukan diagnosis pada pasien di atas?","opts":["Biopsi eksisi","Apusan darah tepi","Aspirasi sumsum tulang","FNAB","DXA"],"ans":0,"why":"Limfadenopati supraklavikula + aksila dengan gejala B (demam, keringat malam, BB turun > 10%) → curiga limfoma. Baku emas diagnosis: BIOPSI EKSISI kelenjar (arsitektur KGB utuh; FNAB tidak cukup). (Kunci tidak ditandai di file; jawaban standar.)","ref":[51],"tags":["Limfoma"],"skdi":"2","src":"self","cards":[{"q":"Baku emas diagnosis limfoma?","a":"Biopsi eksisi KGB"},{"q":"Gejala B limfoma?","a":"Demam, keringat malam, BB turun > 10%"}]},
{"id":"hem-x03","lat":"pj-int2","ln":16,"lp":5,"stem":"Seorang perempuan berusia 30 tahun, datang ke UGD karena demam sejak 1 bulan yang lalu. Keluhan demam hilang timbul disertai batuk, badannya lemah, dan memar-memar di kulit. Pada pemeriksaan fisik didapatkan suhu tubuh 40 C; adanya ulkus di mulut; hepar dan lien tidak teraba; dan ekimosis (+) di lengan dan paha. Pada pemeriksaan darah didapatkan leukosit 2000, Hb 6, MCV 82, MCH 39, Hct 19,6%, trombosit 52.000. Apakah patofisiologi yang mendasari kondisi pasien tersebut?","opts":["Sekuestrasi parasit ke pembuluh darah","Depresi sel induk progenitor di dalam sumsum tulang","Defisiensi substrat pembentuk rantai globin","Maturasi DNA yang terhambat","Defisiensi enzim eritrosit"],"ans":1,"why":"Pansitopenia (leukosit 2000, Hb 6, trombosit 52.000) dengan anemia normositik, infeksi (demam, ulkus mulut), perdarahan, TANPA hepatosplenomegali → anemia aplastik: depresi/kegagalan sel induk (stem cell) sumsum tulang.","ref":[29,30],"tags":["Anemia aplastik"],"skdi":"2","src":"kunci","cards":[{"q":"Anemia aplastik: patofisiologi?","a":"Kegagalan sel induk sumsum tulang"},{"q":"Anemia aplastik: organomegali?","a":"Tidak ada"}]},
{"id":"hem-x04","lat":"pj-int2","ln":17,"lp":6,"stem":"Seorang laki-laki usia 30 tahun mengeluh sering memar pada persendian ketika banyak bekerja. Keluhan tersebut seringkali berulang sedari kecil. Pasien mengaku belum mengetahui penyebab keluhan tersebut. Dari hasil pemeriksaan didapatkan trombosit 280.000 dengan aktivitas faktor IX rendah. Apakah temuan yang paling mungkin ditemukan?","opts":["APTT memanjang","PT memanjang","BT memanjang","APTT memendek","PT memendek"],"ans":0,"why":"Perdarahan sendi berulang sejak kecil + faktor IX rendah → hemofilia B. Jalur intrinsik terganggu → aPTT memanjang; PT, BT, trombosit normal.","ref":[43,45],"tags":["Hemofilia"],"skdi":"2","src":"kunci","cards":[]},
{"id":"hem-x05","lat":"pj-int2","ln":18,"lp":6,"stem":"Perempuan usia 56 tahun berobat dengan keluhan nyeri pinggang sejak 1 tahun ini. Keluhan memberat sejak 6 bulan terakhir. TTV dalam batas normal, namun didapatkan adanya konjungtiva anemis. Hasil Rontgen didapatkan gambaran spike appearance disertai fraktur kompresi lumbal 5-6. Hasil Lab didapatkan Hb 9, leukosit 5800, trombosit 89.000. Rouloux formation (+). Serum Kalsium meningkat, ureum 121, kreatinin 3,1. Apakah diagnosis yang paling mungkin?","opts":["Osteoporosis","Multiple myeloma","Anemia on CKD","Hernia nucleosus pulposus","Anemia penyakit kronis"],"ans":1,"why":"Nyeri tulang/fraktur kompresi, anemia, hiperkalsemia, gangguan ginjal (CRAB) + rouleaux → multiple myeloma.","ref":[56],"tags":["Multiple myeloma"],"skdi":"2","src":"kunci","cards":[{"q":"Kriteria CRAB multiple myeloma?","a":"Calcium ↑, Renal failure, Anemia, Bone lesions"}]},
{"id":"hem-x06","lat":"pj-int2","ln":19,"lp":6,"stem":"Perempuan 18 tahun datang ke Poliklinik dengan keluhan lemas. Tanda vital dalam batas normal. Saat diperiksa tampak adanya sklera ikterik, konjungtiva anemis, dan splenomegali. Pada pemeriksaan penunjang didapatkan Hb 7,0, hapusan darah tepi berbentuk anisopoikilositosis dengan sel target (+), eliptosis, basophilic stippling. Bagaimanakah diagnosis yang tepat?","opts":["Anemia G6PD","Thalasemia","Leukemia","AIHA","Anemia aplastik"],"ans":1,"why":"Anemia hemolitik (ikterik, splenomegali) dengan sel target, anisopoikilositosis, basophilic stippling pada remaja → thalassemia.","ref":[12,13],"tags":["Thalassemia"],"skdi":"2","src":"kunci","cards":[{"q":"Sel target + basophilic stippling + splenomegali?","a":"Thalassemia"}]}
]});
